SET NOCOUNT ON;
SELECT p.panel_code, p.panel_name, p.module_group, p.category, p.mode
FROM yj_panel p
WHERE p.module_group IN (N'智能供应链',N'库存核算',N'采购管理',N'订单管理',N'品质管理',N'委外加工')
  AND p.panel_code NOT IN ('SO_ORDER','SALES_ORDER_DETAIL','SALES_ORDER_STATS','PU_REQ','PU_ORDER','QC_RECV','QC_RETURN','PURCHASE_IN','FINISH_IN','OTHER_IN','OUTSOURCE_IN','SALE_OUT','MATERIAL_OUT','OTHER_OUT','OUTSOURCE_ISSUE','PURCHASE_IN_DETAIL','FINISH_IN_DETAIL','OTHER_IN_DETAIL','OUTSOURCE_IN_DETAIL','SALE_OUT_DETAIL','MATERIAL_OUT_DETAIL','OTHER_OUT_DETAIL','OUTSOURCE_ISSUE_DETAIL','PURCHASE_IN_STATS','FINISH_IN_STATS','OTHER_IN_STATS','OUTSOURCE_IN_STATS','SALE_OUT_STATS','MATERIAL_OUT_STATS','OTHER_OUT_STATS','OUTSOURCE_ISSUE_STATS','STOCK_BALANCE','STOCK_LEDGER','STOCK_SUMMARY','QC_INSP','QC_TC_IN','QC_CATALOG','QC_INSP_REC','QC_INSP_REQ','QC_INSP_REQ_SERIES','QC_OP','QC_RECORD','QC_DISPOSAL','ROD_RETURN','LOT_TRACE','QC_BHG','QC_BHC','QC_BHZ','QC_JJF','QC_SCP','QC_LYB','QC_SCY')
ORDER BY p.module_group, p.panel_code;
GO
